#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.waterfall)]
    public class Waterfall : EffectBehaviour
    {
        public Waterfall(string nsp, string name) : base(nsp, name)
        {

        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.Level.AddLoopSoundEntity(VanillaSoundID.waterfall, entity.ID);
        }
    }
}